def expected_turns(n: int, m: int, jumps: list[list[int]]) -> list[int] | None:
    from fractions import Fraction

    jump = dict(jumps)
    resolved = {}

    def resolve(cell):
        path = []
        while cell in jump and cell not in resolved:
            path.append(cell)
            cell = jump[cell]
        destination = resolved.get(cell, cell)
        for cell in path:
            resolved[cell] = destination
        return destination

    destinations = [resolve(cell) for cell in range(n + 1)]

    # Build the reachable state graph and count die outcomes.
    transitions = {}
    reverse = [[] for _ in range(n + 1)]
    reachable = {0}
    queue = [0]

    for cell in queue:
        if cell == n:
            continue

        counts = {}
        for roll in range(1, m + 1):
            landing = cell + roll
            if landing > n:
                landing = 2 * n - landing
            target = destinations[landing]
            counts[target] = counts.get(target, 0) + 1

        transitions[cell] = counts
        for target in counts:
            reverse[target].append(cell)
            if target not in reachable:
                reachable.add(target)
                queue.append(target)

    # In a finite chain, absorption is almost sure exactly when every
    # reachable state has a path to the terminal state.
    can_finish = {n}
    stack = [n]
    while stack:
        for cell in reverse[stack.pop()]:
            if cell not in can_finish:
                can_finish.add(cell)
                stack.append(cell)

    if not reachable <= can_finish:
        return None

    states = [cell for cell in queue if cell != n]
    index = {cell: i for i, cell in enumerate(states)}
    size = len(states)

    # m * E[cell] - sum(count[target] * E[target]) = m.
    matrix = [[0] * (size + 1) for _ in range(size)]
    for cell, i in index.items():
        matrix[i][i] = m
        matrix[i][size] = m
        for target, count in transitions[cell].items():
            if target != n:
                matrix[i][index[target]] -= count

    # Fraction-free Gaussian elimination (Bareiss algorithm).
    previous_pivot = 1
    for k in range(size - 1):
        if matrix[k][k] == 0:
            pivot_row = next(
                i for i in range(k + 1, size) if matrix[i][k] != 0
            )
            matrix[k], matrix[pivot_row] = matrix[pivot_row], matrix[k]

        pivot_row = matrix[k]
        pivot = pivot_row[k]

        for i in range(k + 1, size):
            row = matrix[i]
            factor = row[k]
            for j in range(k + 1, size + 1):
                row[j] = (
                    pivot * row[j] - factor * pivot_row[j]
                ) // previous_pivot
            row[k] = 0

        previous_pivot = pivot

    expectations = [Fraction(0) for _ in range(size)]
    for i in range(size - 1, -1, -1):
        value = Fraction(matrix[i][size])
        for j in range(i + 1, size):
            if matrix[i][j]:
                value -= matrix[i][j] * expectations[j]
        expectations[i] = value / matrix[i][i]

    answer = expectations[index[0]]
    return [answer.numerator, answer.denominator]
